WITH
    [(133,21600,64800),(134,14400,NULL),(142,43200,NULL),(177,73800,NULL),(189,30600,NULL),(196,75600,NULL),(217,63000,NULL),(231,79200,NULL),(247,21600,64800),(275,10800,NULL),(403,16200,NULL),(427,21600,NULL),(466,66600,NULL),(471,40500,NULL),(489,66600,NULL),(496,18000,NULL),(501,20400,NULL),(517,32400,NULL),(520,16200,NULL),(534,25200,NULL),(576,32400,43200),(636,37800,45000),(663,18000,NULL),(669,19800,NULL),(711,28800,NULL),(735,22800,69600),(747,19800,NULL),(750,10800,NULL),(759,16200,NULL),(802,66600,NULL),(808,48600,NULL),(842,21600,66600),(879,21600,NULL),(960,64800,NULL),(975,43200,68400),(987,21600,NULL),(1001,14400,NULL),(1007,10800,NULL),(1061,19800,NULL),(1136,70200,NULL),(1141,68400,NULL),(1148,68400,NULL),(1157,68400,NULL),(1219,21600,NULL),(1343,21600,NULL),(1351,21600,NULL),(1459,21600,NULL),(1528,64800,NULL),(65805,18000,NULL),(65815,19800,21600),(66007,63000,NULL),(68705,28800,NULL),(68747,68400,NULL),(69526,68400,NULL),(70030,41400,NULL),(70346,21600,NULL),(70429,67500,NULL),(70628,64800,NULL),(71756,10800,NULL),(74130,19800,NULL),(74690,18000,NULL),(75103,25200,NULL),(76480,68400,NULL),(77093,18000,NULL),(77167,19800,NULL),(77705,21600,NULL),(78796,23400,NULL),(80438,63000,NULL),(81826,64800,NULL),(83409,19800,NULL),(84310,68400,NULL),(84832,19800,NULL),(93580,16200,NULL),(94509,66600,NULL),(94515,36000,43200),(94782,39600,NULL),(94877,10800,NULL),(194482,66600,NULL),(196420,18000,72000),(196752,18000,NULL),(197504,16200,NULL),(204358,16200,NULL),(305974,24300,67500)] AS ritual_defs,
    ritual_tbl AS (
        SELECT tupleElement(r, 1) AS DestinationID,
               tupleElement(r, 2) AS ritual1_sec,
               tupleElement(r, 3) AS ritual2_sec
        FROM (SELECT arrayJoin(ritual_defs) AS r)
    )
SELECT
    b.DestinationID,
    b.SourceID,
    count() AS overall_txn,
    countIf(doi_ist_sec < rt.ritual1_sec) AS before_ritual1_txn,
    countIf(rt.ritual2_sec IS NOT NULL AND doi_ist_sec < rt.ritual2_sec) AS before_ritual2_txn,
    uniqExact(b.RouteID) AS overall_routes,
    uniqExactIf(b.RouteID, doi_ist_sec < rt.ritual1_sec) AS before_ritual1_routes,
    uniqExactIf(b.RouteID, rt.ritual2_sec IS NOT NULL AND doi_ist_sec < rt.ritual2_sec) AS before_ritual2_routes
FROM
(
    SELECT
        DestinationID,
        SourceID,
        RouteID,
        (toHour(addMinutes(DateOfIssue, 330)) * 3600
         + toMinute(addMinutes(DateOfIssue, 330)) * 60
         + toSecond(addMinutes(DateOfIssue, 330))) AS doi_ist_sec
    FROM oms_db.bus_ticket_issued
    WHERE Year = toYear(today())
      AND DateOfIssue >= subtractDays(now(), 30)
      AND DestinationID IN (133,134,142,177,189,196,217,231,247,275,403,427,466,471,489,496,501,517,520,534,576,636,663,669,711,735,747,750,759,802,808,842,879,960,975,987,1001,1007,1061,1136,1141,1148,1157,1219,1343,1351,1459,1528,65805,65815,66007,68705,68747,69526,70030,70346,70429,70628,71756,74130,74690,75103,76480,77093,77167,77705,78796,80438,81826,83409,84310,84832,93580,94509,94515,94782,94877,194482,196420,196752,197504,204358,305974)
      AND SourceID IN (121,122,123,124,125,126,129,130,131,133,134,135,136,137,141,154,167,210,216,217,222,229,231,232,233,235,236,246,247,248,255,262,277,284,285,292,293,309,311,313,316,317,318,320,321,324,325,335,338,347,364,390,395,399,403,408,411,413,415,416,418,422,427,443,444,453,455,458,462,467,468,470,472,473,489,496,497,500,501,502,506,517,519,530,551,575,601,602,624,634,635,637,641,646,651,653,654,658,663,664,675,690,696,697,698,701,729,733,734,735,736,737,747,757,759,771,777,802,807,808,809,818,827,833,842,851,911,933,938,960,973,979,981,983,995,1001,1003,1073,1102,1120,1125,1128,1136,1141,1142,1144,1169,1173,1290,1294,1322,1365,1366,1369,1377,1394,1395,1404,1405,1429,1437,1438,1439,1443,1476,1477,1499,1501,1512,1513,1514,1523,1552,1553,1608,1611,65768,65815,65966,65976,65995,66006,66007,68738,68747,68846,69217,69279,69774,69802,69959,69995,70014,70015,70024,70429,70628,70643,71081,71145,71255,71265,71390,71425,71647,71756,71757,71929,71958,73329,73376,73532,73534,73723,74661,74672,74676,74678,74680,74694,74699,74820,74880,75409,75412,75711,75769,76079,76422,76431,76451,76480,76481,77521,77677,77682,77717,77718,77726,78023,78027,79167,79277,79613,79617,79723,81384,81429,81826,82100,82325,82333,82543,82899,82982,83760,84117,84793,84832,85148,85482,85498,85502,85962,87082,87086,88722,90189,90329,90355,90960,91157,92453,92827,93455,93947,93966,93968,94509,94518,94751,94782,94980,95083,95213,95217,95222,95224,95325,95332,95441,95462,95474,95476,95534,194443,195598,195599,197105,197222,197504,198074,198152,198554,198568,200684,201665,201668,204358,204409,204429,215416,215864,215983,216383,216707,216812)
) b
INNER JOIN ritual_tbl rt
    ON b.DestinationID = rt.DestinationID
GROUP BY b.DestinationID, b.SourceID